// Embeds the methodology texts the AI endpoints use into
// api/_lib/knowledge.generated.ts, so every Vercel function carries them
// without reading files at runtime. Run after editing anything in
// metodologie/:  npm run gen:knowledge
// A test fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";

export const KNOWLEDGE_FILES = [
  "data/formulace-vzdelavacich-cilu.md",
  "data/klicove-kompetence.md",
  "data/prurezova-temata.md",
  "data/spravna-formulace-kriterii-hodnoceni.md",
  "data/jedinci-se-specialnimi-vzdelavacimi-potrebami.md",
  "data/jak-psat-slovni-hodnoceni.md",
  "vysvedceni-jinak/02-pojeti-vysvedceni-a-zasady-hodnoceni.md",
  "vysvedceni-jinak/03-prostredky-hodnoceni.md",
  "vysvedceni-jinak/04-slovnicek-pouzitych-vyrazu.md",
  "vysvedceni-jinak/05-hodnoceni-oblasti-chovani-zaka.md",
  "vysvedceni-jinak/06-hodnoceni-v-teoretickych-predmetech.md",
  "vysvedceni-jinak/07-hodnoceni-ve-vychovnych-predmetech.md",
];

export function renderKnowledge() {
  const entries = KNOWLEDGE_FILES.map(
    (f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(`metodologie/${f}`, "utf8"))},`,
  );
  return `// Generated by scripts/build-knowledge.mjs from metodologie/. Do not edit by hand.
export const KNOWLEDGE = {
${entries.join("\n")}
} as const;

export type KnowledgeFile = keyof typeof KNOWLEDGE;
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync("api/_lib/knowledge.generated.ts", renderKnowledge());
  console.log("api/_lib/knowledge.generated.ts updated");
}
